import type { PageParams } from '@/lib/api/types'

/** Quiz types with admin-managed questions. Math questions are generated by the backend. */
export const EDITABLE_QUIZ_TYPES = ['daily', 'giveAnswer'] as const
export type EditableQuizType = (typeof EDITABLE_QUIZ_TYPES)[number]
export type QuizType = EditableQuizType | 'math'

export const QUIZ_TYPE_LABELS: Record<QuizType, string> = {
  daily: 'Daily quiz',
  giveAnswer: 'Give answer',
  math: 'Math quiz',
}

export const ANSWER_TYPES = ['singleChoice', 'text'] as const
export type AnswerType = (typeof ANSWER_TYPES)[number]

export const ANSWER_TYPE_LABELS: Record<AnswerType, string> = {
  singleChoice: 'Single choice',
  text: 'Text answer',
}

export interface QuizOption {
  id: string
  text: string
  isCorrect: boolean
}

export interface QuizQuestion {
  id: string
  quizType: QuizType
  text: string
  answerType: AnswerType
  imageUrl: string | null
  options: QuizOption[]
  acceptedAnswers: string[] | null
  active: boolean
  createdAt: string
  updatedAt: string
}

export interface QuizQuestionRequest {
  id?: string
  quizType: EditableQuizType
  text: string
  answerType: AnswerType
  imageUrl: string | null
  options?: { text: string; correct: boolean }[]
  acceptedAnswers?: string[]
  active: boolean
}

export interface QuizQuestionListParams extends PageParams {
  type?: EditableQuizType | ''
}
